'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  MessageCircle,
  Shield,
  Link as LinkIcon,
  Send,
  Share2,
  Bell,
  Zap,
  Globe,
  Clock,
  Unlock,
  Lock,
  Trash2,
  Copy,
  Check,
  Settings2,
  Sparkles,
  Inbox,
  CornerDownRight,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { HybridStorage } from '@/lib/storage-utils';
import { supabase } from '@/lib/supabase';

interface MessageRow {
  id: string;
  content: string;
  isSeen: boolean;
  timestamp: string;
  expires_at?: string;
  sender_country?: string;
  sender_timezone?: string;
  pre_reply?: string;
}

export default function MessageLandingPage() {
  const [activeTab, setActiveTab] = useState<'inbox' | 'settings'>('inbox');
  const [username, setUsername] = useState('creator');
  const [expiryDays, setExpiryDays] = useState<number>(7); // Default 7 days
  const [isPublicInbox, setIsPublicInbox] = useState(false); // Premium feature
  const [selectedReplies, setSelectedReplies] = useState<string[]>([
    '≡ƒÆ£ I felt this deeply',
    '∩┐╜ Why did you wait this long?',
    '≡ƒÿé I needed to hear this',
    '≡ƒñÉ This stays between us',
    '≡ƒ½ú I always knew...',
    "≡ƒæÇ Say more. I'm listening.",
  ]);
  const [newReply, setNewReply] = useState('');
  const [messages, setMessages] = useState<MessageRow[]>([]);
  const [loading, setLoading] = useState(false);
  const [copiedLink, setCopiedLink] = useState<'inbox' | 'public' | null>(null);

  // Load username & messages
  useEffect(() => {
    const fetchUserAndMessages = async () => {
      setLoading(true);
      try {
        const {
          data: { user },
        } = await supabase.auth.getUser();
        if (user) {
          const name =
            user.user_metadata.username ||
            user.user_metadata.full_name ||
            'creator';
          setUsername(name);
        }

        // Fetch messages from HybridStorage
        const rawMsgs = await HybridStorage.getAll('message');

        // Mock enrich sender locations/timezones for premium user aesthetics
        const mockEnriched: MessageRow[] = rawMsgs.map(
          (m: any, idx: number) => {
            const content = m.content || m;
            const ts = m.timestamp || new Date().toISOString();
            const countries = ['US', 'GB', 'DE', 'FR', 'JP', 'IN', 'CA'];
            const timezones = [
              'EST (UTC-5)',
              'GMT (UTC+0)',
              'CET (UTC+1)',
              'IST (UTC+5.5)',
              'JST (UTC+9)',
            ];

            return {
              id: m.id || `msg-${idx}-${Date.now()}`,
              content: content.content || content,
              isSeen: content.isSeen || false,
              timestamp: ts,
              expires_at:
                content.expires_at ||
                new Date(
                  new Date(ts).getTime() + 7 * 24 * 60 * 60 * 1000,
                ).toISOString(),
              sender_country:
                content.sender_country || countries[idx % countries.length],
              sender_timezone:
                content.sender_timezone || timezones[idx % timezones.length],
              pre_reply: content.pre_reply,
            };
          },
        );

        setMessages(
          mockEnriched.sort(
            (a, b) =>
              new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime(),
          ),
        );
      } catch (err) {
        console.error('Failed to load message assets:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchUserAndMessages();
  }, []);

  const handleCopy = (type: 'inbox' | 'public') => {
    const origin = typeof window !== 'undefined' ? window.location.origin : '';
    const path =
      type === 'inbox' ? `/u/${username}` : `/u/${username}/messages`;
    navigator.clipboard.writeText(`${origin}${path}`);
    setCopiedLink(type);
    toast.success(
      `${type === 'inbox' ? 'Inbox input' : 'Public board'} link copied!`,
    );
    setTimeout(() => setCopiedLink(null), 2000);
  };

  const addReplyOption = () => {
    if (!newReply.trim()) return;
    if (selectedReplies.includes(newReply.trim())) {
      toast.error('Template reply already exists.');
      return;
    }
    setSelectedReplies([...selectedReplies, newReply.trim()]);
    setNewReply('');
    toast.success('Response shortcut added!');
  };

  const removeReplyOption = (reply: string) => {
    setSelectedReplies(selectedReplies.filter((r) => r !== reply));
  };

  const deleteMessage = async (id: string) => {
    try {
      await HybridStorage.delete(id, 'message');
      setMessages(messages.filter((m) => m.id !== id));
      toast.success('Secret message deleted');
    } catch (e) {
      toast.error('Failed to delete message');
    }
  };

  const handleStaticTogglePremium = () => {
    // Scaffold premium lock modal
    toast.info(
      'Γ¡É Premium Upgrade Required: Public boards are limited to developer/pro subscriptions.',
    );
    setIsPublicInbox((prev) => !prev);
  };

  return (
    <div className='relative overflow-hidden min-h-[calc(100vh-64px)] pb-20'>
      {/* Background decoration */}
      <div className='orb orb-primary w-[500px] h-[500px] -top-40 -right-40 opacity-20' />
      <div className='orb orb-secondary w-[400px] h-[400px] bottom-0 -left-20 opacity-15' />

      <div className='container relative mx-auto px-4 sm:px-6 pt-12 max-w-5xl'>
        {/* Header Section */}
        <div className='flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 border-b border-white/5 pb-8'>
          <div>
            <div className='badge border-pw-primary/20 bg-pw-primary/10 text-pw-primary mb-3'>
              <MessageCircle className='h-3.5 w-3.5' />
              AnonLink Inbox Console
            </div>
            <h1 className='text-3xl sm:text-4xl font-extrabold font-display leading-[1.1]'>
              Private message <span className='gradient-text'>Studio.</span>
            </h1>
            <p className='mt-2 text-sm text-pw-muted'>
              Configure expiry parameters, customize pre-reply shortcuts, and
              monitor incoming anonymous cards in real-time.
            </p>
          </div>

          <div className='flex bg-white/5 p-1 rounded-xl border border-white/5'>
            <button
              onClick={() => setActiveTab('inbox')}
              className={`flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'inbox' ? 'bg-pw-primary text-white' : 'text-pw-muted hover:text-pw-text'}`}>
              <Inbox className='h-4 w-4' /> Message Board
            </button>
            <button
              onClick={() => setActiveTab('settings')}
              className={`flex items-center gap-2 px-4 py-2 text-xs font-bold rounded-lg transition-all ${activeTab === 'settings' ? 'bg-pw-primary text-white' : 'text-pw-muted hover:text-pw-text'}`}>
              <Settings2 className='h-4 w-4' /> Link Config
            </button>
          </div>
        </div>

        {/* Tab Content */}
        <AnimatePresence mode='wait'>
          {activeTab === 'inbox' ?
            <motion.div
              key='inbox-tab'
              initial={{ opacity: 0, y: 15 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -15 }}
              className='grid grid-cols-1 lg:grid-cols-12 gap-8'>
              {/* Message Cards */}
              <div className='lg:col-span-8 space-y-6'>
                {messages.length === 0 ?
                  <Card className='card-glow p-12 text-center flex flex-col items-center justify-center min-h-[300px]'>
                    <div className='w-16 h-16 bg-white/5 rounded-full flex items-center justify-center mb-6'>
                      <Inbox className='h-8 w-8 text-pw-muted animate-pulse' />
                    </div>
                    <h3 className='text-lg font-bold'>Your inbox is empty</h3>
                    <p className='text-xs text-pw-muted mt-2 max-w-sm'>
                      Share your secure anonymous link with your audience to
                      start receiving submissions.
                    </p>
                    <Button
                      onClick={() => setActiveTab('settings')}
                      className='btn-primary mt-6 text-xs h-10 px-6 font-bold'>
                      Set Up Links
                    </Button>
                  </Card>
                : <div className='space-y-4'>
                    {messages.map((msg) => (
                      <Card
                        key={msg.id}
                        className='p-6 bg-pw-surface/40 hover:bg-pw-surface/75 border-white/5 transition-all relative overflow-hidden group'>
                        {/* Meta Row */}
                        <div className='flex items-center justify-between gap-4 text-[10px] text-pw-muted font-mono mb-4 border-b border-white/5 pb-3'>
                          <div className='flex flex-wrap items-center gap-3'>
                            <span className='flex items-center gap-1 font-bold text-pw-primary border border-pw-primary/20 bg-pw-primary/10 rounded px-1.5 py-0.5'>
                              <Globe className='h-3 w-3' />{' '}
                              {msg.sender_country || 'Unknown'}
                            </span>
                            <span className='flex items-center gap-1'>
                              <Clock className='h-3 w-3' />{' '}
                              {msg.sender_timezone}
                            </span>
                            {msg.expires_at && (
                              <span className='hidden sm:inline-flex items-center gap-1 text-pw-warning'>
                                Expires:{' '}
                                {new Date(msg.expires_at).toLocaleDateString()}
                              </span>
                            )}
                          </div>

                          <button
                            onClick={() => deleteMessage(msg.id)}
                            className='text-pw-danger hover:text-pw-danger/80 opacity-0 group-hover:opacity-100 transition-opacity p-1'
                            title='Delete secret message'>
                            <Trash2 className='h-4 w-4' />
                          </button>
                        </div>

                        {/* Content text */}
                        <p className='text-white text-base leading-relaxed break-words font-medium pr-6'>
                          &quot;{msg.content}&quot;
                        </p>

                        {/* Pre-reply tags if available */}
                        {msg.pre_reply && (
                          <div className='mt-4 flex items-center gap-2 text-xs text-pw-success font-bold font-mono'>
                            <CornerDownRight className='h-3 w-3 text-pw-success' />
                            <span>Quick Replied: {msg.pre_reply}</span>
                          </div>
                        )}

                        {/* Interactive Pre-Reply Panel */}
                        {!msg.pre_reply && selectedReplies.length > 0 && (
                          <div className='mt-4 pt-3 border-t border-white/5 flex flex-wrap items-center gap-2'>
                            <span className='text-[10px] uppercase font-bold text-pw-muted mr-1'>
                              Pre-reply:
                            </span>
                            {selectedReplies.map((reply) => (
                              <button
                                key={reply}
                                onClick={() => {
                                  setMessages((prev) =>
                                    prev.map((m) =>
                                      m.id === msg.id ?
                                        { ...m, pre_reply: reply }
                                      : m,
                                    ),
                                  );
                                  toast.success('Replied to message cards!');
                                }}
                                className='px-2.5 py-1 text-[11px] font-bold rounded-lg border border-white/5 bg-white/5 text-pw-text hover:bg-pw-primary/10 hover:border-pw-primary/30 transition-all'>
                                {reply}
                              </button>
                            ))}
                          </div>
                        )}
                      </Card>
                    ))}
                  </div>
                }
              </div>

              {/* Sidebar stats/links preview */}
              <div className='lg:col-span-4 flex flex-col gap-6'>
                <Card className='card-glow p-6 space-y-4'>
                  <h4 className='text-xs font-bold uppercase tracking-widest text-pw-muted flex items-center gap-2'>
                    <Sparkles className='h-4 w-4 text-pw-primary' /> Active
                    Statistics
                  </h4>
                  <div className='grid grid-cols-2 gap-4 pt-2'>
                    <div className='p-4 bg-white/5 border border-white/5 rounded-xl'>
                      <span className='text-2xl font-bold font-mono'>
                        {messages.length}
                      </span>
                      <p className='text-[10px] text-pw-muted uppercase font-bold mt-1'>
                        Received
                      </p>
                    </div>
                    <div className='p-4 bg-white/5 border border-white/5 rounded-xl'>
                      <span className='text-2xl font-bold font-mono'>
                        {messages.filter((m) => !m.isSeen).length}
                      </span>
                      <p className='text-[10px] text-pw-muted uppercase font-bold mt-1'>
                        Unread
                      </p>
                    </div>
                  </div>
                </Card>

                <Card className='card-glow p-6 space-y-4'>
                  <h4 className='text-xs font-bold uppercase tracking-widest text-pw-muted'>
                    Interactive Links
                  </h4>
                  <div className='space-y-3'>
                    <div className='p-3 bg-white/5 border border-white/5 rounded-xl flex items-center justify-between'>
                      <div className='truncate'>
                        <span className='text-[10px] block font-bold text-pw-muted uppercase'>
                          Send Message Link
                        </span>
                        <span className='text-xs font-medium text-pw-primary truncate'>
                          /u/{username}
                        </span>
                      </div>
                      <Button
                        size='icon'
                        variant='ghost'
                        onClick={() => handleCopy('inbox')}
                        className='h-8 w-8 text-pw-muted hover:text-pw-primary'>
                        {copiedLink === 'inbox' ?
                          <Check className='h-4 w-4 text-pw-success' />
                        : <Copy className='h-4 w-4' />}
                      </Button>
                    </div>

                    <div className='p-3 bg-white/5 border border-white/5 rounded-xl flex items-center justify-between'>
                      <div className='truncate'>
                        <span className='text-[10px] block font-bold text-pw-muted uppercase flex items-center gap-1.5'>
                          Public Board Link
                          <span className='text-[8px] bg-amber-500/20 text-amber-500 font-bold border border-amber-500/20 rounded px-1 scale-90'>
                            PRO
                          </span>
                        </span>
                        <span className='text-xs font-medium text-pw-secondary truncate'>
                          /u/{username}/messages
                        </span>
                      </div>
                      <Button
                        size='icon'
                        variant='ghost'
                        onClick={() => handleCopy('public')}
                        className='h-8 w-8 text-pw-muted hover:text-pw-secondary'>
                        {copiedLink === 'public' ?
                          <Check className='h-4 w-4 text-pw-success' />
                        : <Copy className='h-4 w-4' />}
                      </Button>
                    </div>
                  </div>
                </Card>
              </div>
            </motion.div>
          : <motion.div
              key='settings-tab'
              initial={{ opacity: 0, y: 15 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -15 }}
              className='grid grid-cols-1 lg:grid-cols-12 gap-8'>
              {/* Main settings options */}
              <div className='lg:col-span-8 space-y-6'>
                <Card className='card-glow p-6 sm:p-8 space-y-6'>
                  <div>
                    <h3 className='text-lg font-bold mb-1'>
                      Message Lifespan & Expiry
                    </h3>
                    <p className='text-xs text-pw-muted'>
                      Messages automatically disappear from the database after
                      this period.
                    </p>
                  </div>

                  <div className='grid grid-cols-2 sm:grid-cols-5 gap-3'>
                    {[
                      { l: '24 Hours', v: 1 },
                      { l: '3 Days', v: 3 },
                      { l: '7 Days', v: 7 },
                      { l: '30 Days', v: 30 },
                      { l: 'Indefinite', v: 0 },
                    ].map((item) => (
                      <button
                        key={item.v}
                        onClick={() => {
                          setExpiryDays(item.v);
                          toast.success(`Expiry length saved to ${item.l}!`);
                        }}
                        className={`h-11 px-3 text-xs font-bold rounded-lg border transition-all ${expiryDays === item.v ? 'bg-pw-primary/10 border-pw-primary text-pw-primary' : 'border-white/10 hover:bg-white/5 text-pw-muted'}`}>
                        {item.l}
                      </button>
                    ))}
                  </div>
                </Card>

                {/* Pre-reply customization */}
                <Card className='card-glow p-6 sm:p-8 space-y-6'>
                  <div>
                    <h3 className='text-lg font-bold mb-1'>
                      Interactive Response Anchors
                    </h3>
                    <p className='text-xs text-pw-muted'>
                      Choose quick templates that senders can click to pre-reply
                      or express feelings.
                    </p>
                  </div>

                  <div className='flex gap-2'>
                    <Input
                      value={newReply}
                      onChange={(e) => setNewReply(e.target.value)}
                      placeholder="Add custom pre-reply (e.g. ≡ƒöÑ Let's play!)"
                      className='bg-white/5 border-white/10 h-11 text-xs'
                      onKeyDown={(e) => e.key === 'Enter' && addReplyOption()}
                    />
                    <Button
                      onClick={addReplyOption}
                      className='btn-primary h-11 px-5 text-xs font-bold'>
                      Add Tag
                    </Button>
                  </div>

                  <div className='flex flex-wrap gap-2 pt-2'>
                    {selectedReplies.map((reply) => (
                      <span
                        key={reply}
                        className='inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold border border-white/10 bg-white/5 rounded-lg text-pw-text'>
                        {reply}
                        <button
                          onClick={() => removeReplyOption(reply)}
                          className='hover:text-pw-danger text-pw-muted text-xs font-bold ml-1'>
                          ├ù
                        </button>
                      </span>
                    ))}
                  </div>
                </Card>
              </div>

              {/* Sidebar premium control */}
              <div className='lg:col-span-4 flex flex-col gap-6'>
                <Card className='card-glow p-6 space-y-6'>
                  <div className='flex justify-between items-start'>
                    <div>
                      <h4 className='text-sm font-bold uppercase tracking-wider'>
                        Public Board
                      </h4>
                      <p className='text-[11px] text-pw-muted mt-1'>
                        Allows anyone to view a directory page of all messages
                        sent to you.
                      </p>
                    </div>
                    <span className='text-[8px] bg-amber-500/20 text-amber-500 font-bold border border-amber-500/20 rounded px-1.5 py-0.5'>
                      PRO
                    </span>
                  </div>

                  <div className='pt-2 border-t border-white/5 flex items-center justify-between'>
                    <span className='text-xs font-bold text-pw-muted flex items-center gap-1.5 font-mono'>
                      {isPublicInbox ?
                        <Unlock className='h-4 w-4 text-amber-500' />
                      : <Lock className='h-4 w-4' />}
                      {isPublicInbox ?
                        'GUEST READ ALLOWED'
                      : 'LOCKED (PRIVATE)'}
                    </span>
                    <button
                      onClick={handleStaticTogglePremium}
                      className={`w-12 h-6 px-1 rounded-full flex items-center transition-all ${isPublicInbox ? 'bg-amber-500 justify-end' : 'bg-white/10 justify-start'}`}>
                      <span className='w-4 h-4 rounded-full bg-white shadow' />
                    </button>
                  </div>
                </Card>
              </div>
            </motion.div>
          }
        </AnimatePresence>
      </div>
    </div>
  );
}
